package hu.synostream.android;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;
/** Owns scanning while the Activity is backgrounded. Never starts a foreground service from a background callback. */
public final class ScanService extends Service {
    private final ScanStarts starts=new ScanStarts();private PowerManager.WakeLock cpu;private SynoApp app;private long lastUpdate;
    @Override public void onCreate(){super.onCreate();app=(SynoApp)getApplication();NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("scan",UiText.context(this).getString(R.string.msg_library_scan_afed43),NotificationManager.IMPORTANCE_LOW));startForeground(42,notification(UiText.context(this).getString(R.string.msg_scanning_the_library_3502b5)));cpu=getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"SynoStream:scan");cpu.acquire(6*60*60*1000L);}

    private Notification notification(String text){PendingIntent open=PendingIntent.getActivity(this,42,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent cancel=PendingIntent.getService(this,43,new Intent(this,ScanService.class).setAction("STOP"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,"scan").setSmallIcon(android.R.drawable.stat_notify_sync).setContentTitle(UiText.context(this).getString(R.string.msg_synostream_library_scan_548fac)).setContentText(UiText.message(this,text)).setContentIntent(open).setOnlyAlertOnce(true).setOngoing(true).addAction(new Notification.Action.Builder(null,UiText.context(this).getString(R.string.msg_cancel_533cb7),cancel).build()).build();}
    void progress(){long now=SystemClock.elapsedRealtime();if(now-lastUpdate>1000){lastUpdate=now;getSystemService(NotificationManager.class).notify(42,notification(app.status));}}
    @Override public int onStartCommand(Intent intent,int flags,int startId){startForeground(42,notification(UiText.context(this).getString(R.string.msg_scanning_the_library_3502b5)));starts.started(startId);if(intent==null||"STOP".equals(intent.getAction())){app.cancelScan();stopSelf();return START_NOT_STICKY;}if(app.scanRunning)return START_NOT_STICKY;try{JSONObject library=new JSONObject(intent.getStringExtra("library"));app.runScan(library,this::progress,()->stopSelf(starts.completionId()),intent.getBooleanExtra("force_metadata",false));}catch(Exception e){app.busy=false;app.status=UiText.context(this).getString(R.string.msg_scanning_could_not_be_started_4314aa);app.changed();stopSelf();}return START_NOT_STICKY;}
    @Override public void onTimeout(int startId,int fgsType){app.cancelScan(true);stopSelf();}
    @Override public void onDestroy(){if(app.scanRunning)app.cancelScan(true);if(cpu!=null&&cpu.isHeld())cpu.release();super.onDestroy();}
    @Override public IBinder onBind(Intent intent){return null;}
}
